INSERT INTO coupon_distribution(id,request_id,request_digest,template_id,mode,config_json,target_count,issued_quantity,
  status,created_by_admin_user_id,created_at,published_at,completed_at)
SELECT #{id},#{key},#{digest},id,#{input.mode},#{config},1,1,'completed',#{actor},#{at},#{at},#{at}
  FROM coupon_template WHERE id=#{input.templateId}
